create type public.user_role as enum ('admin','instructor','student');
create table public.profiles (id uuid primary key references auth.users(id) on delete cascade, full_name text not null, role public.user_role not null default 'student', phone text, medical_notes text, avatar_url text, created_at timestamptz default now());
create table public.students (id uuid primary key default gen_random_uuid(), profile_id uuid references public.profiles(id), discipline text not null, level text default 'Blanco', emergency_contact text, active boolean default true, created_at timestamptz default now());
alter table public.students add column if not exists full_name text; alter table public.students add column if not exists email text; alter table public.students add column if not exists phone text; alter table public.students add column if not exists medical_notes text;
create table public.classes (id uuid primary key default gen_random_uuid(), name text not null, discipline text not null, instructor_id uuid references public.profiles(id), class_date date not null, start_time time not null, end_time time, capacity integer default 20, room text, created_at timestamptz default now());
alter table public.classes add column if not exists instructor_name text; alter table public.classes add column if not exists repeat_weekdays boolean default false; alter table public.classes add column if not exists location text;
create table public.attendance (id uuid primary key default gen_random_uuid(), class_id uuid references public.classes(id) on delete cascade, student_id uuid references public.students(id) on delete cascade, present boolean default true, marked_by uuid references public.profiles(id), marked_at timestamptz default now(), unique(class_id,student_id));
create table public.payments (id uuid primary key default gen_random_uuid(), student_id uuid references public.students(id), amount numeric(12,2) not null, period text not null, status text default 'pending', receipt_url text, paid_at timestamptz, created_at timestamptz default now());
create table public.news (id uuid primary key default gen_random_uuid(), title text not null, body text, image_url text, published boolean default true, created_by uuid references public.profiles(id), created_at timestamptz default now());
create table public.gallery (id uuid primary key default gen_random_uuid(), image_url text not null, caption text, created_by uuid references public.profiles(id), created_at timestamptz default now());
create table public.memberships (id uuid primary key default gen_random_uuid(), name text not null, amount numeric(12,2) not null, active boolean default true, created_by uuid references public.profiles(id), created_at timestamptz default now());
create table public.expenses (id uuid primary key default gen_random_uuid(), concept text not null, amount numeric(12,2) not null, expense_date date default current_date, created_by uuid references public.profiles(id), created_at timestamptz default now());
create table public.trial_bookings (id uuid primary key default gen_random_uuid(), name text not null, contact text, preferred_class text, status text default 'new', created_at timestamptz default now());
create table public.class_enrollments (id uuid primary key default gen_random_uuid(), class_name text not null, user_id uuid references auth.users(id) on delete cascade, created_at timestamptz default now(), unique(class_name,user_id));
create table public.contact_messages (id uuid primary key default gen_random_uuid(), name text not null, contact text not null, message text, created_at timestamptz default now());
alter table public.profiles enable row level security; alter table public.students enable row level security; alter table public.classes enable row level security; alter table public.attendance enable row level security; alter table public.payments enable row level security; alter table public.news enable row level security; alter table public.gallery enable row level security; alter table public.contact_messages enable row level security; alter table public.memberships enable row level security; alter table public.expenses enable row level security; alter table public.trial_bookings enable row level security;
alter table public.class_enrollments enable row level security;
create policy "public classes" on public.classes for select using (true); create policy "public news" on public.news for select using (published=true); create policy "public gallery" on public.gallery for select using (true);
create policy "public contact insert" on public.contact_messages for insert with check (true);
create policy "public trial insert" on public.trial_bookings for insert with check (true);
create policy "users enroll themselves" on public.class_enrollments for insert with check (auth.uid()=user_id);
create policy "users see own enrollments" on public.class_enrollments for select using (auth.uid()=user_id);
create or replace function public.is_staff() returns boolean language sql stable security definer set search_path=public as $$ select exists(select 1 from profiles where id=auth.uid() and role in ('admin','instructor')); $$;
create policy "staff memberships" on public.memberships for all using (public.is_staff()) with check (public.is_staff());
create policy "staff expenses" on public.expenses for all using (public.is_staff()) with check (public.is_staff());
create policy "staff students" on public.students for all using (public.is_staff()) with check (public.is_staff());
create policy "staff attendance" on public.attendance for all using (public.is_staff()) with check (public.is_staff());
create policy "staff payments" on public.payments for all using (public.is_staff()) with check (public.is_staff());
create policy "staff gallery" on public.gallery for all using (public.is_staff()) with check (public.is_staff());
